package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import org.kanger.*;

/** Explicit owning read-only family inspection in the native connection profile, not admission activation. */
public final class SymbolicCacheFamilyInspectionRunner {
    private static int checks;
    private static void need(boolean yes,String reason){checks++;if(!yes)throw new AssertionError(reason);}
    private static Mind open(DB db,Path directory,String name)throws Exception{User u=new User();u.setDatabaseDir(directory.toString()+java.io.File.separator);db.init(u);Mind root=new Mind(u);u.setCurrentMind(root);Mind m=(Mind)root.useStorage(name);u.setCurrentMind(m);return m;}
    private static void close(Mind m)throws Exception{((User)m.getUser()).setCurrentMind(m.closeStorage());}
    private static void seed(Path directory,String name,String text)throws Exception{DB db=new DB();Mind m=open(db,directory,name);try{if(text.isEmpty())need(ContextProductionInventory.inspect(m,db.getContextId(),db.getRevision(),true,Collections.emptyList(),1000).primary.isEmpty(),"empty physical Source fixture");else need(m.compile(text,null,false),"family physical fixture "+name);}finally{close(m);}}
    private static boolean refuses(SymbolicCacheFamilyInspection result,DB db,Mind source)throws Exception{try{result.requireCurrent(db,source);return false;}catch(Exception expected){return true;}}
    private static void initialized()throws Exception{
        Path directory=Files.createTempDirectory("symbolic-family-provider-");seed(directory,"Source","!marker(9);");seed(directory,"Target","!@u rel(1,u,1)->middle(u); !@u middle(u)->tail(u);");DB db=new DB();Mind source=open(db,directory,"Source");long published;SymbolicCacheFamilyInspection saved;
        try{db.connectContext("Target");db.saveConnections(source);db.applyConnectionCommand(source,"Target","!$u rel(1,u,1);");db.saveConnections(source);long revision=db.getRevision(),targetRevision=db.versionHistory("Target").getCurrentRevision();String before=ContextProductionInventory.inspect(source,db.getContextId(),revision,true,Collections.emptyList(),1000).fingerprint;
            saved=db.inspectSymbolicCacheFamily(source);saved.requireCurrent(db,source);need(saved.model.status==ContextDependentModelSearchInspection.Status.MODELLED_PENDING,"provider family constructed and independently checked: "+saved.model.status+" "+saved.model.reason);need(saved.members.size()==1&&saved.members.get(0).working.inventory.generated.size()==2&&!saved.members.get(0).working.inventory.dependentPrimaryView(),"actual initialized symbolic member is modeled through a private projection, raw inventory stays closed");need(saved.model.originalRows==5&&saved.model.finalObligations==saved.model.runtimeObligations,"only original rows become model axioms and complete final/native counts agree");need(revision==db.getRevision()&&targetRevision==db.versionHistory("Target").getCurrentRevision()&&before.equals(ContextProductionInventory.inspect(source,db.getContextId(),revision,true,Collections.emptyList(),1000).fingerprint),"read-only family check publishes nothing and preserves actual source");
            final SymbolicCacheFamilyInspection current=saved;final DB owner=db;final Mind q=source;ContextDependentForeignCacheSnapshotRunner.withNoGood(source,()->need(refuses(current,owner,q),"source branch restriction invalidates whole-family evidence"));saved.requireCurrent(db,source);
            db.applyConnectionCommand(source,"Target","!private(2);");need(refuses(saved,db,source),"changed complete private recipe invalidates family result");saved=db.inspectSymbolicCacheFamily(source);need(saved.model.status==ContextDependentModelSearchInspection.Status.MODELLED_PENDING&&saved.members.get(0).initialization.size()==2,"fresh family uses complete extended private view");published=db.saveConnections(source);need(refuses(saved,db,source),"source publication requires fresh whole-family evidence");saved=db.inspectSymbolicCacheFamily(source);
        }finally{close(source);}
        need(refuses(saved,db,source),"closed owner cannot reuse family receipt");db=new DB();source=open(db,directory,"Source");try{SymbolicCacheFamilyInspection reopened=db.inspectSymbolicCacheFamily(source);need(db.getRevision()==published&&reopened.model.status==ContextDependentModelSearchInspection.Status.MODELLED_PENDING&&reopened.members.get(0).initialization.size()==2,"cold source reopen rechecks every physical member and full recipe before family model");need(refuses(saved,db,source),"new adapter cannot reuse old family owner authority");}finally{close(source);}
    }
    private static void independent(boolean reverse)throws Exception{
        Path directory=Files.createTempDirectory("symbolic-independent-family-");seed(directory,"Source","");seed(directory,"A","!p(1);");seed(directory,"B","!~p(1);");DB db=new DB();Mind source=open(db,directory,"Source");try{db.connectContext(reverse?"B":"A");db.connectContext(reverse?"A":"B");db.saveConnections(source);SymbolicCacheFamilyInspection result=db.inspectSymbolicCacheFamily(source);need(result.model.status==ContextDependentModelSearchInspection.Status.MODELLED_PENDING&&result.members.size()==2&&result.model.models.size()==3,"independent sibling disagreement does not become an A/B union in owning family profile");db.disconnectContext("A");need(refuses(result,db,source),"removed member invalidates complete family manifest");}finally{close(source);}
    }
    public static void main(String[] args)throws Exception{System.setProperty("user.home",Files.createTempDirectory("symbolic-family-storage-").toString());initialized();independent(false);independent(true);System.out.println("SYMBOLIC_CACHE_FAMILY_INSPECTION_PASS checks="+checks);}
}
